"""Next authored unit from individually read lib/bitmap.c; integrate after768."""
def register(topic,q,detail):
    def lesson(title,symbol,why,principle,use,reading,qa,cards):
        topic(title,'자료구조·알고리즘','lib/bitmap.c',symbol,why,principle,use,reading,
              *(q(*x) for x in qa),details=[detail(*x) for x in cards])
    lesson('Bitmap 비교·유효 Bit와 마지막 Word Mask','__bitmap_equal',
      '작은 상태 집합을 unsigned long 배열에 저장할 때 남은 저장 bit와 실제 의미 있는 bit를 구분합니다.',
      '__bitmap_equal은 완전한 word들을 직접 비교하고 마지막 부분 word는 XOR 결과에 BITMAP_LAST_WORD_MASK를 적용합니다. __bitmap_or_equal도 두 입력의 OR와 세 번째 입력을 같은 방식으로 비교합니다. 유효 bits가 word 크기의 배수가 아니어도 그 밖의 tail bit는 이 비교의 결과에 영향을 주지 않습니다.',
      '각 bitmap의 실제 저장공간과 같은 유효 bit 수를 제공합니다. Unused tail이 언제나 0이라고 가정하지 않고 scalar 비교의 mask를 확인합니다. 모든 다른 변환 함수가 tail을 자동 정리한다고 이 비교만으로 확대하지 않습니다.',
      '전체 word 수, 마지막 XOR/mask, bits0 경로를 읽으세요.',
      [('65bit 집합에서 bit70만 다르면 equal 결과는?', '유효 영역이 같으면 true이다','저장 word가 다르므로 반드시 false이다','두 번째 word는 첫 한 bit만 유효합니다. 마지막 mask가 bit70 차이를 제거합니다.'),
       ('Or Equal은 새 OR bitmap을 반드시 할당하는가?', 'Word마다 OR 결과를 직접 비교한다','전체 임시 bitmap을 먼저 할당한다','각 word의 OR와 대상 word를 비교하며 부분 word도 mask를 적용합니다. Allocator 호출은 없습니다.')],
      [('저장 구조','64bit long 환경의 65bit bitmap은 두 unsigned long word를 사용합니다. 두 번째 word의 63bit는 유효 영역 밖입니다. 32bit 환경의 word 개수는 다릅니다.'),
       ('빈 집합','내부 비교의 bits0 경로는 word loop와 tail branch를 실행하지 않아 true입니다. 유효 주소와 저장 계약은 사용하는 상위 API 문맥과 함께 확인합니다.')])
    lesson('Bitmap 집합 연산·Tail 처리와 Mask 교체','__bitmap_replace',
      '교집합·합집합·차집합과 선택 bit 교체를 word 연산으로 구현하는 원리를 배웁니다.',
      'AND는 A&B,ANDNOT는 A&~B를 저장하고 남은 tail을 mask한 뒤 결과가 비어 있지 않은지 bool로 반환합니다. OR·XOR·complement는 저장 word마다 해당 연산을 적용하지만 tail을 별도 0으로 만들지 않습니다. Replace는 (old&~mask)|(new&mask)로 선택된 bit만 새 값을 사용합니다.',
      '같은 유효 bit 수의 충분한 입력·목적 배열을 제공합니다. 복수 word 전체의 연산은 원자적 snapshot이 아니므로 동시 변경과 별도 동기화를 확인합니다. Tail이 의미 있는 비교·개수에 들어가지 않도록 각 API의 mask 계약을 지킵니다.',
      '두 영역의 OR 결합, AND/ANDNOT 반환 누적, word 반복을 읽으세요.',
      [('Replace의 mask bit가 0인 위치에서는?', 'old의 bit를 유지한다','new의 bit를 무조건 쓴다','old&~mask가 선택되지 않은 위치를 보존하고 new&mask가 선택한 위치를 채웁니다.'),
       ('내부 OR가 마지막 미사용 bit를 언제나 0으로 만드는가?', '전체 저장 word를 OR하므로 그렇지 않다','모든 bit 연산이 tail을 강제로 0으로 만든다','OR body에는 마지막 mask 처리가 없습니다. 유효 bit의 의미와 저장 tail을 구분합니다.')],
      [('차집합','A&~B는 A에 있고 B에는 없는 원소입니다. ~B 자체를 출력한 complement와 같은 집합은 아닙니다.'),
       ('한 Word와 여러 Word','Header의 작은 상수 bit 수 경로는 한 word 연산을 사용할 수 있습니다. lib/bitmap.c의 반복 body가 모든 호출에서 그대로 실행된다고 가정하지 않습니다.')])
    lesson('Bitmap 관계·교차와 부분집합의 반례','__bitmap_subset',
      'Boolean 관계를 전체 bitmap 생성 없이 word별 조기 종료로 판정하는 원리를 배웁니다.',
      'Intersects는 A&B가 한 word라도 비zero이면 true입니다. Subset은 A&~B가 한 word라도 비zero이면 false입니다. 마지막 부분 word에는 유효 mask를 적용합니다. 아무 반례가 없으면 subset은 true,공통 원소가 없으면 intersects는 false를 반환합니다.',
      '유효 bit 수와 입력 수명·동시 변경 조건을 맞춥니다. Subset 방향 A⊆B를 반대로 읽지 않습니다. Boolean 반환은 bit의 개수나 첫 위치를 제공하지 않습니다.',
      'A&B와 A&~B, 반례 조기 반환, tail mask를 읽으세요.',
      [('A가 {1},B가 {1,2}이면 subset(A,B)는?', 'true이다','B에 추가 원소가 있으므로 false이다','A&~B에는 bit가 없습니다. B에 더 많은 원소가 있어도 A의 포함 관계는 성립합니다.'),
       ('Intersects true가 의미하는 것은?', '공통 set bit가 하나 이상 있다','두 bitmap의 모든 bit가 같다','한 word의 비zero 교집합만으로 true를 반환합니다. Equal 검사와 다릅니다.')],
      [('빈 집합의 관계','A가 비어 있으면 어떤 B에도 subset입니다. A와 B 중 하나가 비어 있으면 교차는 false입니다. Loop의 최종 반환을 이 사례와 연결합니다.'),
       ('알고리즘 비용','최악에는 유효 저장 word를 모두 읽지만 앞에서 공통 원소나 반례를 찾으면 끝냅니다. 집합 결과 배열을 따로 만들 필요가 없습니다.')])
    lesson('Bitmap Weight·Popcount와 식 재사용','__bitmap_weight',
      'Set bit 개수를 세는 함수와 교집합·차집합 개수 계산을 같은 반복 구조로 연결합니다.',
      'BITMAP_WEIGHT 매크로는 전체 word의 hweight_long을 누적하고 마지막 부분 word는 유효 mask를 적용합니다. Weight는 bitmap[idx],Weight AND는 A[idx]&B[idx],Weight ANDNOT는 A[idx]&~B[idx]를 FETCH로 전달합니다. 서로 다른 식을 같은 loop에 넣어 임시 집합을 만들지 않고 개수를 셉니다.',
      '개수를 저장 word 수나 가장 높은 set bit 위치와 구분합니다. FETCH의 식이 loop의 idx와 연결되는 매크로 계약을 읽습니다. Tail의 set bit는 유효 개수에 포함하지 않습니다.',
      'FETCH, local idx와 w, 부분 word mask, 세 wrapper를 읽으세요.',
      [('집합 {0,5,63}의 weight는?', '3이다','64이다','Weight는 set bit 개수입니다. 가장 높은 위치에 1을 더한 저장 길이와 다릅니다.'),
       ('Weight AND가 먼저 교집합 배열을 할당하는가?', '식 A&B를 바로 popcount한다','별도 배열을 반드시 만든다','FETCH가 각 word의 결합 식입니다. 원본은 임시 bitmap allocation을 수행하지 않습니다.')],
      [('Popcount','hweight_long은 하나의 unsigned long에 들어 있는 1bit 수를 셉니다. Architecture의 실제 instruction 선택은 그 helper 구현과 빌드 설정의 별도 영역입니다.'),
       ('정수 반환','유효 영역의 bit 수보다 결과가 커지지 않습니다. 동시 writer가 있으면 서로 다른 word를 다른 시점에 읽을 수 있으므로 일관된 snapshot은 외부 계약입니다.')])
    lesson('Bitmap Right Shift·Word 경계 Carry와 Tail','__bitmap_shift_right',
      '여러 word에 걸친 bit 집합을 오른쪽으로 이동할 때 이웃 word의 일부 bit를 이어 붙이는 원리를 배웁니다.',
      'Shift를 off=shift/BITS_PER_LONG과 rem으로 나눕니다. 목적 word는 src[off+k]>>rem과 위 word의 낮은 rem bit를 높은 자리로 옮긴 부분을 OR합니다. 원본 마지막 word를 읽을 때 유효 mask를 적용합니다. 낮은 목적 word부터 써서 정확한 in-place 이동을 가능하게 하고 off만큼의 높은 목적 word는 0으로 채웁니다.',
      'Helper가 처리할 수 있는 유효 shift와 충분한 배열 공간을 caller가 보장합니다. 임의로 큰 shift를 자동 clamp하는 함수가 아닙니다. 작은 상수 header 경로의 단일 word shift 조건도 별도로 확인합니다.',
      'off/rem, rem0의 특별 분기, 마지막 input mask, 높은 zero fill을 읽으세요.',
      [('Shift가 word 크기의 배수이면 upper 결합을 하는가?', 'rem0이라 upper를 0으로 둔다','항상 word 크기만큼 left shift한다','rem0 분기는 BITS_PER_LONG-rem shift를 실행하지 않습니다. Word 단위 이동만 필요합니다.'),
       ('In-place right shift에서 먼저 쓰는 쪽은?', '낮은 목적 word이다','항상 가장 높은 목적 word이다','낮은 목적은 더 높은 원본을 읽습니다. 원본이 아직 덮이지 않도록 loop가 낮은 쪽부터 진행합니다.')],
      [('저장과 의미','마지막 원본 word의 미사용 bit가 오른쪽 이동으로 유효 영역에 들어오지 않도록 mask를 적용합니다. Mask의 위치가 입력을 읽는 부분이라는 점을 확인합니다.'),
       ('범위 전제','off가 저장 word 수를 넘으면 끝의 memset 위치와 크기가 유효하지 않을 수 있습니다. 불가능한 shift까지 모든 입력을 안전하게 처리한다고 설명하지 않습니다.')])
    lesson('Bitmap Left Shift·역순 순회와 Carry','__bitmap_shift_left',
      '같은 배열에서 bit를 높은 위치로 이동할 때 loop 방향이 원본 자료 보존에 중요함을 배웁니다.',
      'Shift를 word off와 rem으로 나누고 높은 k부터 내려옵니다. Src[k]<<rem과 아래 word의 높은 rem bit를 낮은 자리로 가져온 부분을 OR하여 dst[k+off]에 씁니다. 낮은 off word는 0으로 채웁니다. 이 내부 body는 마지막 목적 tail을 별도 mask하지 않습니다.',
      '유효 shift와 같은 크기의 충분한 배열을 제공합니다. In-place일 때 높은 쪽부터 진행하는 이유를 자료 의존성으로 읽습니다. 결과의 미사용 tail을 의미 있는 bit로 다루는 후속 작업에는 각 API의 계약을 확인합니다.',
      '높은 k→낮은 k, 아래 word 읽기, dst[k+off], 낮은 zero fill을 읽으세요.',
      [('낮은 목적부터 쓰도록 바꾸면 가능한 문제는?', '아직 읽을 원본 word를 덮을 수 있다','계산 결과가 모든 입력에서 동일하다','높은 위치로 이동하는 in-place에서는 낮은 원본이 나중에도 필요할 수 있습니다. 순회 방향이 수명 역할을 합니다.'),
       ('이 내부 함수가 tail을 언제나 clear하는가?', '별도 마지막 mask가 없다','끝에서 항상 LAST_WORD_MASK를 적용한다','Source body에는 마지막 목적 word mask가 없습니다. Header의 작은 상수 경로와도 구분합니다.')],
      [('방향 비교','Right는 위 원본을 읽으며 낮은 목적부터,Left는 아래 원본을 읽으며 높은 목적부터 씁니다. 두 loop의 방향은 단순 스타일 차이가 아닙니다.'),
       ('전제와 단위','off는 word 개수,rem은 bit 개수입니다. Byte offset과 바꾸어 계산하지 않으며 shift가 허용 저장 범위를 넘지 않게 합니다.')])
    lesson('Bitmap Cut·부분 겹침과 Bit별 Carry','bitmap_cut',
      '선택 구간을 제거하고 뒤 bit를 당길 때 겹치는 입력·출력과 앞쪽 자료 보존을 함께 처리합니다.',
      '첫 word에서 first 아래 bit를 keep에 저장하고 memmove로 전체 저장 word를 복사합니다. Cut 횟수만큼 first의 word부터 오른쪽으로 한 bit씩 이동하며 다음 word의 최하위 bit를 carry로 받아 높은 자리에 붙입니다. 마지막에는 first 아래 bit를 keep으로 복구합니다. 이 body는 마지막 입력 tail을 정리하지 않습니다.',
      'first가 실제 저장 구간에 있고 필요한 크기의 배열이라는 조건을 지킵니다. 겹침은 memmove 계약으로 처리합니다. 미사용 높은 tail이 이동 후 유효 영역으로 내려올 수 있어 필요하면 caller가 tail을 정리한 입력을 제공합니다.',
      'keep 저장→memmove→cut 반복→carry→앞 bit 복구를 읽으세요.',
      [('First보다 낮은 bit는 어떻게 보존하는가?', '처음 keep에 저장하고 마지막에 복원한다','모든 shift가 알아서 앞 bit를 건드리지 않는다','첫 부분 word도 shift되므로 별도 keep과 복구가 필요합니다.'),
       ('부분 겹침 복사에서 사용한 함수는?', 'memmove이다','겹침이 금지된 memcpy만 사용한다','원본 문서는 부분 또는 전체 겹침을 허용합니다. 초기 전체 word 복사를 memmove로 수행합니다.')],
      [('실제 반복 비용','한 번의 큰 shift가 아니라 cut개 bit마다 word들을 이동합니다. Cut 값과 이동 word 수가 반복 비용에 함께 영향을 줍니다.'),
       ('Tail의 차이','일반 scalar 관계 함수의 tail mask를 이 변환 body에도 있다고 가정하지 않습니다. 마지막 저장 word를 그대로 이동하는 구현의 입력 조건을 별도 확인합니다.')])
    lesson('Bitmap Set Clear·첫 Mask와 마지막 Mask','__bitmap_set',
      '임의 연속 bit 구간을 변경할 때 부분 word 두 개와 그 사이 전체 word를 다루는 원리를 배웁니다.',
      'Start의 word와 BITMAP_FIRST_WORD_MASK로 시작합니다. 남은 len이 현재 word의 남은 bit 수 이상이면 mask를 적용하고 다음 word부터 full mask를 씁니다. 마지막 길이가 남으면 BITMAP_LAST_WORD_MASK(start+len_original)와 결합합니다. Clear는 같은 구조에서 mask의 NOT를 AND합니다.',
      'Start와 비음수 len의 합이 유효 배열 범위에 들어가도록 합니다. Bitmap 저장 용량을 이 helper가 인자로 받지 않아 자동 범위 검사를 하지 않습니다. 복수 word 변경은 전체가 하나의 원자적 동작이 아닙니다.',
      'BIT_WORD,첫 word 남은 수,full mask 전환,마지막 size mask를 읽으세요.',
      [('Start63,len3의 64bit word 환경에서는?', '첫 word bit63과 다음 word bit0·1을 바꾼다','첫 word 안의 세 bit만 바꾼다','Start에서 word 끝까지 한 bit를 처리하고 다음 word에 남은 두 bit를 적용합니다.'),
       ('이 함수가 목적 bitmap의 전체 capacity를 검사하는가?', 'caller가 구간과 공간을 보장해야 한다','nbits 전체 한도를 별도 인자로 항상 받는다','인자는 map,start,len입니다. 전체 allocation 크기를 비교하는 검사는 없습니다.')],
      [('Set과 Clear','Set은 OR로 지정 bit를 켜고 Clear는 AND NOT로 끕니다. 범위 밖의 같은 word bit는 부분 mask가 보존합니다.'),
       ('Header 빠른 경로','상수 1bit,작은 상수 구간,정렬된 byte 구간은 header의 다른 경로를 사용할 수 있습니다. 내부 loop만 보고 모든 호출의 기계 동작을 단정하지 않습니다.')])
    lesson('Bitmap Zero Area·Alignment Offset과 재검색','bitmap_find_next_zero_area_off',
      '연속 빈 자원 범위를 찾을 때 단일 빈 bit 탐색·정렬·전체 구간 검사로 후보를 좁히는 원리를 배웁니다.',
      'Find_next_zero_bit로 시작 후보를 얻고 index+align_offset을 align_mask로 올림한 뒤 offset을 뺍니다. End=index+nr가 size를 넘으면 그 end를 반환합니다. 후보 구간에 set bit가 있으면 그 위치+1을 새 start로 하여 재검색합니다. Set bit가 없으면 index를 반환합니다.',
      'align_mask는 2의 거듭제곱보다 1 작은 값이고 합·끝 계산의 유효 범위를 caller가 보장합니다. 찾은 뒤 실제 예약은 별도 동작이므로 공유 bitmap의 검색·표시 사이를 동기화합니다. 실패 값이 항상 size 하나라고 가정하지 않습니다.',
      'find zero→offset alignment→end check→find set→restart를 읽으세요.',
      [('Alignment가 적용되는 값은?', 'index+align_offset이다','index만 항상 align_offset과 무관하게 정렬된다','원본은 합을 정렬한 다음 offset을 뺍니다. 반환 index 자체가 alignment 배수일 필요는 없습니다.'),
       ('성공 반환 즉시 해당 bit들이 자동 예약되는가?', '검색만 수행한다','찾는 동안 전체 영역을 set한다','Body에는 map 변경이 없습니다. Caller의 실제 예약과 동시 접근 보호가 필요합니다.')],
      [('재시도 시작','막힌 bit의 i+1부터 찾습니다. 같은 충돌을 다시 검사하는 반복을 피하지만 다음 정렬 후보도 전체 구간의 빈 상태를 검사해야 합니다.'),
       ('실패 계약','end>size에서 end를 반환하므로 실패 값이 size보다 클 수 있습니다. 반환을 인덱스로 쓰기 전에 요청 구간이 들어가는지 확인합니다.')])
    lesson('Bitmap Remap·위치 순번과 Modulo 대상','bitmap_remap',
      'Set bit의 실제 위치와 집합 안에서 몇 번째인지라는 순번을 서로 변환하는 mapping을 배웁니다.',
      'bitmap_pos_to_ord는 유효 set 위치인지 확인하고 그 앞의 weight를 순번으로 반환합니다. Remap은 src의 각 set bit를 old 집합 순번 n으로 바꾸고 new의 n%weight(new)번째 set 위치로 보냅니다. Old 밖이거나 new가 비었으면 원래 위치를 유지합니다. Dst==src이면 아무 변화 없이 반환하고 다른 dst는 먼저 clear합니다. Bitremap은 한 위치만 같은 규칙으로 변환합니다.',
      'Dst가 입력 mapping 자료를 파괴하지 않게 분리하고 모든 bitmap의 유효 범위를 맞춥니다. Modulo 때문에 여러 원소가 같은 위치로 모일 수 있음을 이해합니다. In-place 호출을 실제 remapping 지원으로 해석하지 않습니다.',
      'pos>=nbits,test_bit,prefix weight,n%w,find_nth와 identity를 읽으세요.',
      [('Old의 세 번째 set bit가 new의 weight2로 옮겨지면?', '순번2%2=0인 new 첫 위치이다','new의 세 번째 위치가 반드시 존재한다','Set 순번은 0부터 셉니다. 대상 weight로 modulo하여 위치를 선택합니다.'),
       ('Dst==src인 remap 호출은?', '원본을 그대로 두고 반환한다','내부 임시 배열로 완전한 in-place remap을 수행한다','원본은 이 조건에서 즉시 반환합니다. 별도 임시 배열 allocation은 없습니다.')],
      [('부분 Identity','Old domain에 없는 src 위치는 자기 자신으로 보냅니다. 전체 집합을 old의 원소로만 제한하는 필터가 아닙니다.'),
       ('Rank 계산','pos 앞 weight가 순번입니다. 실제 bit 위치가 100이어도 그 앞 set bit가 두 개라면 순번은 2입니다. 물리 위치와 집합 내부 순서를 구분합니다.')])
    lesson('Bitmap Onto·밀집 순번을 희소 위치로','bitmap_onto',
      '밀집된 선택 번호를 sparse 자원 집합의 실제 위치로 옮기는 mapping 원리를 배웁니다.',
      'CONFIG_NUMA의 bitmap_onto는 dst를 clear하고 relmap의 set 위치 n을 순회하면서 순번 m을 증가시킵니다. Orig의 bit m이 켜져 있으면 dst의 실제 bit n을 켭니다. Relmap의 weight 이상인 orig 번호는 어떤 위치에도 대응하지 않습니다. Dst==orig이면 변경 없이 반환합니다.',
      'Orig를 자원 실제 위치가 아니라 relmap의 0-based 선택 순번 집합으로 사용합니다. Dst와 mapping 입력을 분리합니다. 필요하면 먼저 fold로 순번을 대상 weight 안으로 줄이되 빈 relmap 조건을 확인합니다.',
      'relmap 순회,n과 m의 역할,test_bit(m,orig),dst의 n을 읽으세요.',
      [('Relmap={10,20,30},orig={1}이면 dst는?', '{20}이다','{1}이다','Orig의 1은 두 번째 set 위치를 선택합니다. Relmap의 실제 두 번째 위치는 20입니다.'),
       ('Orig의 bit9만 set인데 relmap weight가3이면?', '대응 위치가 없어 결과는 빈 집합이다','자동으로 modulo3을 적용한다','Onto 자체에는 modulo가 없습니다. Fold와 결합할 때만 그 별도 변환을 먼저 수행합니다.')],
      [('상위 CONFIG','이 body는 CONFIG_NUMA 안에 있습니다. Bitmap 자료구조의 일반 표현과 특정 helper의 선택 빌드를 구분합니다.'),
       ('주석과 Body','설명의 간략 pseudo loop 일부가 orig에서 nth를 찾는 형태지만 실제 body는 relmap의 set 위치를 순회합니다. 결과와 문제 풀이를 실제 실행 body 기준으로 확인합니다.')])
    lesson('Bitmap Fold·Modulo 충돌과 크기 조건','bitmap_fold',
      '더 큰 선택 번호를 작은 번호 공간으로 접을 때 modulo와 중복 합쳐짐을 이해합니다.',
      'CONFIG_NUMA의 bitmap_fold는 dst!=orig일 때 목적을 clear하고 orig의 각 set 위치 oldbit에 대해 oldbit%sz를 dst에 set합니다. 서로 다른 위치가 같은 나머지를 가지면 하나의 bit로 합쳐집니다. Dst==orig이면 변경 없이 반환합니다. Sz=0의 별도 방어 branch는 없습니다.',
      'Sz는 양수이고 결과 나머지 위치가 목적 유효 공간에 들어가도록 합니다. 원소 개수가 항상 보존되는 permutation이라고 생각하지 않습니다. 빈 relmap weight를 그대로 divisor로 넘기지 않습니다.',
      'dst clear,for_each set,oldbit%sz,in-place return을 읽으세요.',
      [('Orig={0,10,20},sz10이면 결과는?', '{0}이다','세 개의 서로 다른 위치를 그대로 보존한다','세 위치의 나머지가 모두 0입니다. Set bit는 중복을 하나의 원소로 합칩니다.'),
       ('Sz0도 이 함수가 자동 처리하는가?', 'caller가 양수 sz를 보장해야 한다','언제나 빈 bitmap을 안전하게 반환한다','실제 set 원소에 modulo0을 적용하는 것을 막는 branch가 없습니다.')],
      [('결합의 목적','Fold 후 Onto는 큰 순번을 유한 자원 집합에 순환 배치할 수 있습니다. 목표 집합 weight가 양수라는 전제를 유지합니다.'),
       ('빈 입력','Dst가 분리되어 있고 orig가 비면 clear 뒤 loop가 없습니다. 그 사례만으로 sz0의 모든 입력을 안전하게 처리한다고 일반화하지 않습니다.')])
    lesson('Bitmap 할당·Word 올림과 Node 선택','bitmap_alloc',
      '필요 bit 수를 저장 배열 크기로 바꾸고 초기화·NUMA 요청 옵션을 전달하는 방법을 배웁니다.',
      'Bitmap_alloc은 BITS_TO_LONGS(nbits)개 unsigned long을 kmalloc_array로 요청합니다. Zalloc은 __GFP_ZERO를 OR합니다. Node variant는 kmalloc_array_node에 node를 전달하고 node zalloc도 ZERO를 추가합니다. Bitmap_free는 kfree로 해제합니다.',
      '성공 여부와 선택 flags의 sleep·실패 계약을 확인하고 할당 수명에 맞춰 free합니다. Alloc과 zalloc의 초기 자료 차이를 구분합니다. Node 인자를 실제 placement의 무조건 보장이라고 일반화하지 않습니다.',
      'BITS_TO_LONGS,sizeof(unsigned long),ZERO OR,node 전달,free를 읽으세요.',
      [('64bit long의 65bit 요청에는 몇 word가 필요한가?', '2word이다','1word이다','유효 bit 수를 word 크기로 올림합니다. 마지막 word는 일부 bit만 의미가 있습니다.'),
       ('Alloc도 Zalloc처럼 모든 bit를 0으로 초기화하는가?', 'Zalloc이 ZERO flag를 추가한다','두 wrapper는 항상 같은 flags이다','원본의 차이는 __GFP_ZERO 전달입니다. 초기 내용은 선택한 allocation 계약에 따릅니다.')],
      [('Checked Array','Word 개수와 원소 크기의 곱셈은 kmalloc_array의 checked allocation 경로와 연결됩니다. 이 helper만으로 allocator의 모든 동작을 설명한 것은 아닙니다.'),
       ('영 개수','nbits0도 allocator의 zero-size 반환 계약과 연결됩니다. 실제 저장 자료가 없는 special pointer와 NULL 실패의 의미를 해당 allocation API로 확인합니다.')])
    lesson('Devm Bitmap·Action 등록 실패의 Reset','devm_bitmap_alloc',
      'Device 수명에 맞춰 자원을 정리할 때 allocation과 cleanup 등록을 하나의 성공 조건으로 만드는 원리를 배웁니다.',
      '일반 bitmap allocation이 실패하면 NULL입니다. 성공하면 devm_add_action_or_reset에 devm_bitmap_free와 bitmap을 넘깁니다. 등록이 실패하면 action_or_reset이 해제 동작을 수행하고 wrapper는 NULL을 반환합니다. 성공하면 device 정리 시 action이 bitmap_free를 호출합니다. Zalloc variant는 ZERO flag를 더합니다.',
      'Device 관리 자원의 수명과 manual allocation을 구분합니다. Action 등록 실패에서 이미 reset된 객체를 다시 free하지 않습니다. 성공한 devm 자원도 임의 manual free로 중복 cleanup이 생기지 않게 관리합니다.',
      'allocation→action_or_reset→ret 검사,callback의 bitmap_free를 읽으세요.',
      [('Cleanup 등록만 실패한 경우 bitmap은?', 'action_or_reset의 reset 동작이 정리한다','원본 wrapper가 영원히 누수시킨다','Callback을 함께 넘긴 or_reset API가 실패 시 정리를 수행합니다. Wrapper는 NULL로 실패를 알립니다.'),
       ('Devm Zalloc이 추가하는 flag는?', '__GFP_ZERO이다','항상 모든 GFP flags를 제거한다','기존 flags를 유지하며 ZERO를 OR해 관리 allocation 경로에 넘깁니다.')],
      [('소유권 이전','Allocation 성공만으로 wrapper가 성공한 것은 아닙니다. Cleanup 등록까지 성공해야 device가 관리할 자원을 caller에게 반환합니다.'),
       ('Callback의 단순함','devm_bitmap_free는 void pointer를 bitmap pointer로 읽어 일반 free에 연결합니다. Word 내용에 대한 별도 scan이나 bit 수정은 없습니다.')])
    lesson('Bitmap 배열 변환·U32 U64와 Tail Clear','bitmap_from_arr32',
      'Native unsigned long bitmap과 명시적 폭의 숫자 배열을 변환할 때 host order와 마지막 유효 bit를 이해합니다.',
      '64bit long의 from_arr32는 u32 두 개를 낮은 32bit와 높은 32bit로 묶고 to_arr32는 반대로 나눕니다. 32bit long의 arr64 변환은 u64를 낮은 word와 필요한 높은 word로 나누거나 합칩니다. 각 변환은 마지막 유효 bit 밖을 clear합니다. Header의 같은 폭 경로는 copy_clear_tail을 사용합니다.',
      '입력과 목적의 실제 원소 개수 및 host byte order 계약을 맞춥니다. Network wire encoding으로 자동 변환하는 함수가 아닙니다. 64bit 배열과 작은 마지막 공간의 크기를 실제로 계산하고 CONFIG별 선택 경로를 확인합니다.',
      'halfwords 올림,i/2,32bit shift,32bit 분기의 마지막 음수 index 조건을 읽으세요.',
      [('U32 배열 {1,2}를 64bit word로 묶으면?', '낮은32bit1,높은32bit2이다','CPU와 무관하게 두 원소를 문자열로 이어 붙인다','원본은 (unsigned long)buf[1]<<32를 낮은 값에 OR합니다. Host 수치 배열 변환입니다.'),
       ('이 변환들은 마지막 tail을 어떻게 처리하는가?', 'nbits 밖의 bit를 clear한다','모든 변환에서 tail을 그대로 보존한다','각 body의 마지막 mask는 tail을 정리합니다. 일반 OR·complement의 dontcare 저장 계약과 다릅니다.')],
      [('Zero 길이','변환 loop와 마지막 mask의 nbits 조건은 길이0에서 마지막 원소의 음수 index 접근을 막습니다. 32bit from_arr64의 bitmap[-1]는 loop 뒤 한 칸 다음 pointer와 조건을 함께 읽습니다.'),
       ('실행 증거의 범위','32bit와64bit source 분기를 설명하되64bit host의 unsigned long을 그대로32bit native ABI라고 바꾸어 계산하지 않습니다. 실제32bit 실행 여부는 검증 기록에서 별도 명시합니다.')])
